max_S = 0.0
best_n, best_p, best_q = None, None, None

for n in [10, 11, 12]:
    for p in range(1, 101):
        for q in range(1, 101):
            S = (12 + n) / p + (13 - n) / q
            if S < 1.0:
                if S > max_S:
                    max_S = S
                    best_n = n
                    best_p = p
                    best_q = q

print("\n--- Search Results ---")
print(f"Maximum S found: {max_S}")
if best_n is not None:
    print(f"Achieved with (n, p, q): ({best_n}, {best_p}, {best_q})")
else:
    print("No solution found for S < 1 in the search range.")

